struct SkipListNode {
    const void* value;
    std::vector<std::atomic<SkipListNode*>> forward;
    std::atomic<bool> marked;
    std::atomic<bool> fullyLinked;
};

struct SkipListNode {
    const void* value;
    int level;  // 新增：记录这个节点实际被分配了几层
    std::vector<std::atomic<SkipListNode*>> forward;
    std::atomic<bool> marked;
    std::atomic<bool> fullyLinked;
};

bool LockFreeSkipList::findNode(...) const {
    bool found = false;
    SkipListNode* pred = head_;
    for (int i = maxLevel_; i >= 0; --i) {
        SkipListNode* curr = pred->forward[i].load(acquire);   // L1
        while (true) {
            SkipListNode* succ = curr->forward[i].load(acquire);  // L2
            if (curr != tail_ && compareFunc_(curr->value, value) < 0) {  // L3
                pred = curr;
                curr = succ;
            } else {
                break;
            }
        }
        preds[i] = pred;
        succs[i] = curr;
        if (curr != tail_ && compareFunc_(curr->value, value) == 0) {
            found = true;
        }
    }
    return found;
}

bool LockFreeSkipList::findNode(...) const {
    SkipListNode* pred = head_;
    for (int level = maxLevel_; level >= 0; --level) {
        SkipListNode* curr = pred->forward[level].load(acquire);  // L1
        while (true) {
            if (curr == tail_ || curr == nullptr) break;           // L2 新增
            SkipListNode* next = curr->forward[level].load(acquire); // L3
            if (compareFunc_(curr->value, value) < 0) {             // L4 去掉冗余判断
                pred = curr;
                curr = next;
            } else {
                break;
            }
        }
        preds[level] = pred;
        succs[level] = curr;
    }
    SkipListNode* curr = succs[0];
    return curr != tail_ && compareFunc_(curr->value, value) == 0;
}

for (int i = 1; i < topLevel; ++i) {
    while (true) {
        pred = preds[i];
        succ = succs[i];
        if (pred->forward[i].compare_exchange_strong(succ, newNode, ...)) {
            break;
        }
        findNode(value, preds, succs);  // 刷新了 preds/succs
    }
}

for (int i = 1; i < topLevel; ++i) {
    while (true) {
        pred = preds[i];
        succ = succs[i];
        newNode->forward[i].store(succ, relaxed);  // 关键：先写 forward 指向最新 succ
        if (pred->forward[i].compare_exchange_strong(succ, newNode, ...)) {
            break;
        }
        findNode(value, preds, succs);
    }
}

// 修复前：从 maxLevel(16) 开始
for (int i = maxLevel_; i >= 0; --i) {

// 修复后：从节点实际层数开始
for (int i = nodeToRemove->level - 1; i >= 0; --i) {

// 修复前
if (pred->forward[i].compare_exchange_strong(succ, next, ...)) break;
findNode(value, preds, succs);  // 返回值被忽略

// 修复后
if (pred->forward[i].compare_exchange_strong(succ, next, ...)) break;
if (!findNode(value, preds, succs)) {
    return;  // 节点已被其他线程摘除，直接退出
}

// 修复前：直接 delete，其他线程可能还在读这个节点
destroyNode(nodeToRemove);

// 修复后：延迟回收
retireNode(nodeToRemove);

SkipListNode* next = curr->forward[i].load(acquire);
// 新增：跳过逻辑删除但还没物理摘除的节点
while (next != tail_ && next->marked.load(acquire)) {
    next = next->forward[i].load(acquire);
}

void LockFreeSkipList::retireNode(SkipListNode* node) {
    uint64_t epoch = e.global_epoch.load(relaxed);
    bool needReclaim = false;
    {
        std::lock_guard lock(retired_mutex_);
        retired_.push_back({node, epoch});
        needReclaim = (retired_.size() > 64);  // 原来这行在锁外，TSan race
    }
    if (needReclaim) tryReclaim();
}

void LockFreeSkipList::tryReclaim() {
    uint64_t current = e.global_epoch.load(relaxed);
    bool allObserved = true;
    for (int i = 0; i < e.next_tid; ++i) {
        if (e.threads[i].active.load(acquire)) {
            if (e.threads[i].epoch.load(acquire) < current) {
                allObserved = false;
                break;
            }
        }
    }
    if (!allObserved) {
        e.global_epoch.store(current + 1, release);
        return;
    }
    // 所有线程都观察到了 current，可以安全回收旧节点
    std::lock_guard lock(retired_mutex_);
    for (auto& r : retired_) {
        if (r.epoch < current) delete r.node;
    }
}
